     1→import {DataAvailabilityStatus, EffectiveBalanceIncrements} from "@lodestar/state-transition";
     2→import {CachedBeaconStateAllForks} from "@lodestar/state-transition";
     3→import {
     4→  AttesterSlashing,
     5→  BeaconBlock,
     6→  Epoch,
     7→  IndexedAttestation,
     8→  Root,
     9→  RootHex,
    10→  Slot,
    11→  ValidatorIndex,
    12→} from "@lodestar/types";
    13→import {LVHExecResponse, MaybeValidExecutionStatus, ProtoBlock, ProtoNode} from "../protoArray/interface.js";
    14→import {UpdateAndGetHeadOpt} from "./forkChoice.js";
    15→import {CheckpointWithHex} from "./store.js";
    16→
    17→export type CheckpointHex = {
    18→  epoch: Epoch;
    19→  root: RootHex;
    20→};
    21→
    22→export type CheckpointsWithHex = {
    23→  justifiedCheckpoint: CheckpointWithHex;
    24→  finalizedCheckpoint: CheckpointWithHex;
    25→};
    26→
    27→export type CheckpointHexWithBalance = {
    28→  checkpoint: CheckpointWithHex;
    29→  balances: EffectiveBalanceIncrements;
    30→};
    31→
    32→export type CheckpointHexWithTotalBalance = CheckpointHexWithBalance & {
    33→  totalBalance: number;
    34→};
    35→
    36→export enum EpochDifference {
    37→  current = 0,
    38→  previous = 1,
    39→}
    40→
    41→export enum AncestorStatus {
    42→  CommonAncestor,
    43→  Descendant,
    44→  NoCommonAncenstor,
    45→  BlockUnknown,
    46→}
    47→
    48→export type AncestorResult =
    49→  | {code: AncestorStatus.CommonAncestor; depth: number}
    50→  | {code: AncestorStatus.Descendant}
    51→  | {code: AncestorStatus.NoCommonAncenstor}
    52→  | {code: AncestorStatus.BlockUnknown};
    53→
    54→// Reason for not proposer boost reorging
    55→export enum NotReorgedReason {
    56→  HeadBlockIsTimely = "headBlockIsTimely",
    57→  ParentBlockNotAvailable = "parentBlockNotAvailable",
    58→  ProposerBoostReorgDisabled = "proposerBoostReorgDisabled",
    59→  NotShufflingStable = "notShufflingStable",
    60→  NotFFGCompetitive = "notFFGCompetitive",
    61→  ChainLongUnfinality = "chainLongUnfinality",
    62→  ParentBlockDistanceMoreThanOneSlot = "parentBlockDistanceMoreThanOneSlot",
    63→  ReorgMoreThanOneSlot = "reorgMoreThanOneSlot",
    64→  ProposerBoostNotWornOff = "proposerBoostNotWornOff",
    65→  HeadBlockNotWeak = "headBlockNotWeak",
    66→  ParentBlockNotStrong = "parentBlockNotStrong",
    67→  NotProposingOnTime = "notProposingOnTime",
    68→  NotProposerOfNextSlot = "notProposerOfNextSlot",
    69→  HeadBlockNotAvailable = "headBlockNotAvailable", // Should not happen because head block should be in cache
    70→  Unknown = "unknown", // A placeholder in case reason is not provided
    71→}
    72→
    73→export type ShouldOverrideForkChoiceUpdateResult =
    74→  | {shouldOverrideFcu: true; parentBlock: ProtoBlock}
    75→  | {shouldOverrideFcu: false; reason: NotReorgedReason};
    76→
    77→export interface IForkChoice {
    78→  irrecoverableError?: Error;
    79→
    80→  /**
    81→   * Returns the block root of an ancestor of `block_root` at the given `slot`. (Note: `slot` refers
    82→   * to the block that is *returned*, not the one that is supplied.)
    83→   *
    84→   * ## Specification
    85→   *
    86→   * Equivalent to:
    87→   *
    88→   * https://github.com/ethereum/consensus-specs/blob/v1.1.10/specs/phase0/fork-choice.md#get_ancestor
    89→   */
    90→  getAncestor(blockRoot: RootHex, ancestorSlot: Slot): RootHex;
    91→  /**
    92→   * Run the fork choice rule to determine the head.
    93→   *
    94→   * ## Specification
    95→   *
    96→   * Is equivalent to:
    97→   *
    98→   * https://github.com/ethereum/consensus-specs/blob/v1.1.10/specs/phase0/fork-choice.md#get_head
    99→   */
   100→  getHeadRoot(): RootHex;
   101→  getHead(): ProtoBlock;
   102→  updateAndGetHead(mode: UpdateAndGetHeadOpt): {
   103→    head: ProtoBlock;
   104→    isHeadTimely?: boolean;
   105→    notReorgedReason?: NotReorgedReason;
   106→  };
   107→  /**
   108→   * This is called during block import when proposerBoostReorg is enabled
   109→   * fcu call in `importBlock()` will be suppressed if this returns true. It is also
   110→   * called by `predictProposerHead()` during `prepareNextSlot()`.
   111→   */
   112→  shouldOverrideForkChoiceUpdate(
   113→    blockRoot: RootHex,
   114→    secFromSlot: number,
   115→    currentSlot: Slot
   116→  ): ShouldOverrideForkChoiceUpdateResult;
   117→  /**
   118→   * Retrieves all possible chain heads (leaves of fork choice tree).
   119→   */
   120→  getHeads(): ProtoBlock[];
   121→  /**
   122→   * Retrieve all nodes for the debug API.
   123→   */
   124→  getAllNodes(): ProtoNode[];
   125→  getFinalizedCheckpoint(): CheckpointWithHex;
   126→  getJustifiedCheckpoint(): CheckpointWithHex;
   127→  /**
   128→   * Add `block` to the fork choice DAG.
   129→   *
   130→   * ## Specification
   131→   *
   132→   * Approximates:
   133→   *
   134→   * https://github.com/ethereum/consensus-specs/blob/v1.1.10/specs/phase0/fork-choice.md#on_block
   135→   *
   136→   * It only approximates the specification since it does not run the `state_transition` check.
   137→   * That should have already been called upstream and it's too expensive to call again.
   138→   *
   139→   * ## Notes:
   140→   *
   141→   * The supplied block **must** pass the `state_transition` function as it will not be run here.
   142→   */
   143→  onBlock(
   144→    block: BeaconBlock,
   145→    state: CachedBeaconStateAllForks,
   146→    blockDelaySec: number,
   147→    currentSlot: Slot,
   148→    executionStatus: MaybeValidExecutionStatus,
   149→    dataAvailabilityStatus: DataAvailabilityStatus
   150→  ): ProtoBlock;
   151→  /**
   152→   * Register `attestation` with the fork choice DAG so that it may influence future calls to `getHead`.
   153→   *
   154→   * ## Specification
   155→   *
   156→   * Approximates:
   157→   *
   158→   * https://github.com/ethereum/consensus-specs/blob/v1.1.10/specs/phase0/fork-choice.md#on_attestation
   159→   *
   160→   * It only approximates the specification since it does not perform
   161→   * `is_valid_indexed_attestation` since that should already have been called upstream and it's
   162→   * too expensive to call again.
   163→   *
   164→   * ## Notes:
   165→   *
   166→   * The supplied `attestation` **must** pass the `in_valid_indexed_attestation` function as it
   167→   * will not be run here.
   168→   */
   169→  onAttestation(attestation: IndexedAttestation, attDataRoot: string, forceImport?: boolean): void;
   170→  /**
   171→   * Register attester slashing in order not to consider their votes in `getHead`
   172→   *
   173→   * ## Specification
   174→   *
   175→   * https://github.com/ethereum/consensus-specs/blob/v1.2.0-rc.3/specs/phase0/fork-choice.md#on_attester_slashing
   176→   */
   177→  onAttesterSlashing(slashing: AttesterSlashing): void;
   178→  getLatestMessage(validatorIndex: ValidatorIndex): LatestMessage | undefined;
   179→  /**
   180→   * Call `onTick` for all slots between `fcStore.getCurrentSlot()` and the provided `currentSlot`.
   181→   */
   182→  updateTime(currentSlot: Slot): void;
   183→
   184→  /**
   185→   * Returns current time slot.
   186→   */
   187→  getTime(): Slot;
   188→  /**
   189→   * Returns `true` if the block is known **and** a descendant of the finalized root.
   190→   */
   191→  hasBlock(blockRoot: Root): boolean;
   192→  hasBlockHex(blockRoot: RootHex): boolean;
   193→  /**
   194→   * Same to hasBlock, but without checking if the block is a descendant of the finalized root.
   195→   */
   196→  hasBlockUnsafe(blockRoot: Root): boolean;
   197→  hasBlockHexUnsafe(blockRoot: RootHex): boolean;
   198→  getSlotsPresent(windowStart: number): number;
   199→  /**
   200→   * Returns a `ProtoBlock` if the block is known **and** a descendant of the finalized root.
   201→   */
   202→  getBlock(blockRoot: Root): ProtoBlock | null;
   203→  getBlockHex(blockRoot: RootHex): ProtoBlock | null;
   204→  getFinalizedBlock(): ProtoBlock;
   205→  getJustifiedBlock(): ProtoBlock;
   206→  /**
   207→   * Returns true if the `descendantRoot` has an ancestor with `ancestorRoot`.
   208→   *
   209→   * Always returns `false` if either input roots are unknown.
   210→   * Still returns `true` if `ancestorRoot===descendantRoot` (and the roots are known)
   211→   */
   212→  isDescendant(ancestorRoot: RootHex, descendantRoot: RootHex): boolean;
   213→  /**
   214→   * Prune items up to a finalized root.
   215→   */
   216→  prune(finalizedRoot: RootHex): ProtoBlock[];
   217→  setPruneThreshold(threshold: number): void;
   218→  /**
   219→   * Iterates backwards through ancestor block summaries, starting from a block root
   220→   */
   221→  iterateAncestorBlocks(blockRoot: RootHex): IterableIterator<ProtoBlock>;
   222→  getAllAncestorBlocks(blockRoot: RootHex): ProtoBlock[];
   223→  /**
   224→   * The same to iterateAncestorBlocks but this gets non-ancestor nodes instead of ancestor nodes.
   225→   */
   226→  getAllNonAncestorBlocks(blockRoot: RootHex): ProtoBlock[];
   227→  /**
   228→   * Returns both ancestor and non-ancestor blocks in a single traversal.
   229→   */
   230→  getAllAncestorAndNonAncestorBlocks(blockRoot: RootHex): {ancestors: ProtoBlock[]; nonAncestors: ProtoBlock[]};
   231→  getCanonicalBlockAtSlot(slot: Slot): ProtoBlock | null;
   232→  getCanonicalBlockClosestLteSlot(slot: Slot): ProtoBlock | null;
   233→  /**
   234→   * Returns all ProtoBlock known to fork-choice. Must not mutated the returned array
   235→   */
   236→  forwarditerateAncestorBlocks(): ProtoBlock[];
   237→  /**
   238→   * Iterates forward descendants of blockRoot. Does not yield blockRoot itself
   239→   */
   240→  forwardIterateDescendants(blockRoot: RootHex): IterableIterator<ProtoBlock>;
   241→  getBlockSummariesByParentRoot(parentRoot: RootHex): ProtoBlock[];
   242→  getBlockSummariesAtSlot(slot: Slot): ProtoBlock[];
   243→  /** Returns the distance of common ancestor of nodes to the max of the newNode and the prevNode. */
   244→  getCommonAncestorDepth(prevBlock: ProtoBlock, newBlock: ProtoBlock): AncestorResult;
   245→  /**
   246→   * Optimistic sync validate till validated latest hash, invalidate any decendant branch if invalidated branch decendant provided
   247→   */
   248→  validateLatestHash(execResponse: LVHExecResponse): void;
   249→
   250→  /**
   251→   * A dependent root is the block root of the last block before the state transition that decided a specific shuffling
   252→   */
   253→  getDependentRoot(block: ProtoBlock, atEpochDiff: EpochDifference): RootHex;
   254→}
